"use client"

import * as React from "react"
import { highlight } from "sugar-high"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0nlytype/roll"
import { Button } from "@/components/ui/button"

type SourceProps = Omit<React.ComponentProps<"figure">, "children"> & {
  code: string
  /** The file's name. Wide, it stands in the margin the way a score names its instrument. */
  title?: React.ReactNode
  /** Hide the Copy action. */
  noCopy?: boolean
  /**
   * system (the default): a bracket joins every line. gloss: whole-line comments leave the code for the
   * outer margin, beside the line they explain. passage: the bracket gathers to the lines in `passage`,
   * which stay in ink while the rest recede.
   */
  variant?: "system" | "gloss" | "passage"
  /** passage: the first and last line to mark, counted from 1. */
  passage?: [number, number]
  /** Turn long lines over, hanging (the default). false keeps each line whole and the lines scroll sideways under the numbers. */
  wrap?: boolean
  /** The language, named in the margin under the file's name, the way a score marks its key. */
  language?: string
}

const escape = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")

/**
 * Indentation you can see: a proportional face makes two spaces nearly nothing, so each line's
 * leading spaces become --i (a tab counts two) and the line is indented by that many half-ems.
 * Turnovers hang beneath it, like verse.
 */
function indent(html: string, code: string, variant: SourceProps["variant"], passage?: [number, number]) {
  const src = code.split("\n")
  const lead = src.map((l) => l.match(/^[ \t]*/)![0])
  const lines = html.split("\n").map((line, n) => {
    const space = lead[n] ?? ""
    let drop = space.length
    const depth = space.length + (space.match(/\t/g)?.length ?? 0)
    // gloss: a line that is only a comment becomes a note; its slashes are dropped where it stands in the margin.
    const note = variant === "gloss" ? src[n]?.match(/^\s*\/\/\s?(.*)$/) : null
    if (note)
      return `<span class="sh__line" data-gloss><span class="sh__token--comment"><span class="ot-source-slashes">// </span>${escape(note[1])}</span></span>`
    let out = ""
    let i = 0
    while (i < line.length && drop > 0) {
      if (line[i] === "<") {
        const end = line.indexOf(">", i) + 1
        out += line.slice(i, end)
        i = end
      } else if (line[i] === " " || line[i] === "\t") {
        drop--
        i++
      } else break
    }
    const marked = variant === "passage" && passage && n + 1 >= passage[0] && n + 1 <= passage[1]
    const attrs = marked ? `data-passage style="--i:${depth};--k:${n + 1 - passage[0]}"` : `style="--i:${depth}"`
    return (out + line.slice(i)).replace(/^<span class="sh__line">/, `<span class="sh__line" ${attrs}>`)
  })
  // Consecutive notes travel together, so a note of two lines stays one block beside its line.
  let joined = ""
  lines.forEach((l, n) => {
    const gloss = l.includes("data-gloss")
    const was = n > 0 && lines[n - 1].includes("data-gloss")
    if (gloss && !was) joined += `<span class="ot-source-gloss">`
    if (!gloss && was) joined += `</span>`
    joined += l
  })
  if (lines.at(-1)?.includes("data-gloss")) joined += `</span>`
  return joined // the lines are blocks: a newline between them would open a blank line
}

/**
 * Code, set as type. Weight is the only highlighting: the language's words are ink at 500, signs recede
 * to pencil, and what someone wrote (strings, JSX text, comments) is the expression italic.
 * A bracket joins the lines like a system in a score; copying runs the accent down it once.
 */
function Source({ code, title, noCopy = false, variant = "system", passage, wrap = true, language, className, ...props }: SourceProps) {
  const text = code.replace(/\n$/, "")
  const [from, to] = passage ?? [0, 0]
  const html = React.useMemo(() => indent(highlight(text), text, variant, [from, to]), [text, variant, from, to])
  const [copied, setCopied] = React.useState(0)
  const pre = React.useRef<HTMLPreElement>(null)

  // gloss: two notes on neighbouring lines would sit on each other, so a note that would overlap the one
  // above steps down just clear of it, the way a book's sidenotes queue.
  React.useLayoutEffect(() => {
    const el = pre.current
    if (variant !== "gloss" || !el) return
    const notes = [...el.querySelectorAll<HTMLElement>(".ot-source-gloss")]
    const lay = () => {
      notes.forEach((n) => (n.style.translate = ""))
      el.style.removeProperty("--ot-source-tail")
      if (getComputedStyle(notes[0] ?? el).position !== "absolute") return
      let floor = -Infinity
      for (const n of notes) {
        const r = n.getBoundingClientRect()
        const push = Math.max(0, floor - r.top)
        if (push) n.style.translate = `0 ${push}px`
        floor = r.bottom + push + 4
      }
      const over = floor - el.getBoundingClientRect().bottom
      if (over > 0) el.style.setProperty("--ot-source-tail", `${over}px`)
    }
    lay()
    const ro = new ResizeObserver(lay)
    ro.observe(el)
    return () => ro.disconnect()
  }, [variant, html, copied])

  return (
    <figure data-slot="source" data-variant={variant} data-wrap={wrap ? undefined : "off"} data-copied={copied || undefined} className={cn("ot-source", className)} {...props}>
      <div className="ot-source-frame">
        {title || language || !noCopy ? (
          <figcaption data-slot="source-meta" className="ot-source-meta">
            {title ? <span className="ot-source-name">{typeof title === "string" ? named(title) : title}</span> : null}
            {language ? <span className="ot-source-lang">{language}</span> : null}
            {noCopy ? null : <CopyButton text={code} onCopied={() => setCopied((c) => c + 1)} />}
          </figcaption>
        ) : null}
        {/* Code reads left to right on any page. Keyed by the copy count, so each copy replays the run down the bracket. */}
        {/* Unwrapped, the lines scroll inside <code> while the numbers and the bracket stay on the <pre>; the scroller takes focus, so the arrows scroll it. */}
        <pre ref={pre} key={copied} className="ot-source-code" dir="ltr" tabIndex={wrap ? 0 : undefined} data-lines={text.split("\n").length}>
          <code tabIndex={wrap ? undefined : 0} dangerouslySetInnerHTML={{ __html: html }} />
        </pre>
      </div>
    </figure>
  )
}

/** A file name with its extension set back in pencil; a long path may break after a slash. */
function named(title: string) {
  const dot = title.lastIndexOf(".")
  const cut = dot > 0 && dot > title.lastIndexOf("/") ? dot : title.length
  return (
    <>
      {title
        .slice(0, cut)
        .split(/(?<=\/)/)
        .map((part, i) => (
          <React.Fragment key={i}>
            {i ? <wbr /> : null}
            {part}
          </React.Fragment>
        ))}
      {cut < title.length ? <span className="ot-source-ext">{title.slice(cut)}</span> : null}
    </>
  )
}

type CopyButtonProps = React.ComponentProps<typeof Button> & {
  text: string
  /** Called once the text is on the clipboard. */
  onCopied?: () => void
}

/** Copy keeps its name through the flow: Copy, then Copied. */
function CopyButton({ text, onCopied, variant = "quiet", className, ...props }: CopyButtonProps) {
  const label = React.useRef<HTMLSpanElement>(null)
  const [copied, setCopied] = React.useState(false)
  const timer = React.useRef<ReturnType<typeof setTimeout>>(undefined)

  React.useEffect(() => () => clearTimeout(timer.current), [])

  const show = (next: boolean) => {
    if (label.current) roll(label.current, () => setCopied(next), "0.5em", next ? 1 : -1)
    else setCopied(next)
  }

  return (
    <Button
      variant={variant}
      data-slot="source-copy"
      className={cn("ot-source-copy", className)}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text)
        } catch {
          return // the browser refused; the label stays "Copy", which is true
        }
        onCopied?.()
        show(true)
        clearTimeout(timer.current)
        timer.current = setTimeout(() => show(false), 1800)
      }}
      {...props}
    >
      <span className="ot-source-copy-word">
        <span ref={label} aria-live="polite">
          {copied ? "Copied" : "Copy"}
        </span>
        {/* The room for the longer word, so Copied never moves what stands beside the button. */}
        <span aria-hidden="true">Copied</span>
      </span>
    </Button>
  )
}

export { Source, CopyButton, type SourceProps, type CopyButtonProps }

@layer components {
  /* ── ot-source ── code, set as type. Weight is the only highlighting: the language's words
     are ink at 500, signs recede to pencil, and what someone wrote (strings, JSX text, comments)
     is the expression italic. A bracket joins the lines like a system in a score, the line
     numbers stand before it like bar numbers, and wide, the file's name stands in the margin
     the way a score names its instrument. Copying runs the accent down the bracket once. */
  .ot-source { --ot-source-gutter: 2.75rem; --ot-source-lh: 1.625rem; container-type: inline-size; margin: 0; min-width: 0; }
  .ot-source-frame { display: grid; grid-template-columns: minmax(0, 1fr); row-gap: var(--ot-space-3); }

  .ot-source-meta {
    display: flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--ot-space-4); row-gap: var(--ot-space-1);
    padding-inline-start: var(--ot-source-gutter);
    font-size: var(--ot-pp); line-height: var(--ot-pp-lh); letter-spacing: var(--ot-pp-tr); color: var(--ot-graphite);
  }
  .ot-source-name { min-width: 0; overflow-wrap: anywhere; }
  .ot-source-ext { color: var(--ot-pencil); }
  /* The language, marked like a score's key: small capitals in the pencil, under the name. */
  .ot-source-lang { font-variant-caps: all-small-caps; letter-spacing: 0.08em; color: var(--ot-pencil); }
  .ot-source-copy { margin-inline-start: auto; }
  .ot-source-meta > .ot-source-copy { font-size: inherit; }
  .ot-source-copy-word { display: inline-grid; justify-items: end; }
  .ot-source-copy-word > * { grid-area: 1 / 1; }
  .ot-source-copy-word > [aria-hidden] { visibility: hidden; }

  /* Wide enough for a margin: the name and Copy stand to the left of the lines. */
  @container (min-width: 34rem) {
    .ot-source-frame:has(> .ot-source-meta) { grid-template-columns: 8.5rem minmax(0, 1fr); column-gap: var(--ot-space-3); }
    .ot-source-meta { flex-direction: column; align-items: flex-start; row-gap: var(--ot-space-2); padding-inline-start: 0; padding-block-start: 0.4em; }
    .ot-source-copy { margin-inline-start: 0; }
    .ot-source-copy-word { justify-items: start; }
  }

  .ot-source-code {
    position: relative; margin: 0; padding-block: 0.25rem; padding-inline-start: var(--ot-source-gutter);
    counter-reset: ot-line; white-space: pre-wrap; overflow-wrap: anywhere;
    font-family: var(--ot-voice); font-stretch: 88%; font-size: 0.9375rem; line-height: var(--ot-source-lh); letter-spacing: 0.005em;
    font-variant-numeric: tabular-nums lining-nums; color: var(--ot-graphite);
    --sh-keyword: var(--ot-ink); --sh-entity: var(--ot-ink); --sh-class: var(--ot-ink);
    --sh-identifier: var(--ot-graphite); --sh-property: var(--ot-graphite);
    --sh-string: var(--ot-ink); --sh-jsxliterals: var(--ot-ink);
    --sh-sign: var(--ot-pencil); --sh-comment: var(--ot-pencil); --sh-space: inherit;
  }
  .ot-source-code:focus-visible { outline-offset: 6px; }
  .ot-source-code > code { display: block; font: inherit; }

  /* Each line hangs: indented by its depth, its turnovers a step further in. */
  .ot-source-code .sh__line {
    position: relative; display: block; min-block-size: var(--ot-source-lh);
    padding-inline-start: calc(var(--i, 0) * 0.5em + 1.5em); text-indent: -1.5em;
  }
  .ot-source-code .sh__line::before {
    counter-increment: ot-line; content: counter(ot-line) / "";
    position: absolute; inset-block-start: 0.1em; inset-inline-start: calc(-1 * var(--ot-source-gutter)); width: calc(var(--ot-source-gutter) - 1.35rem);
    text-align: end; text-indent: 0; font-size: 0.75em; font-stretch: 100%; color: var(--ot-pencil); opacity: 0.6;
    transition: opacity var(--ot-allegro), color var(--ot-allegro);
  }
  .ot-source-code .sh__line:hover::before { opacity: 1; color: var(--ot-ink); }
  .ot-source-code[data-lines="1"] .sh__line::before { content: none; }

  .ot-source-code .sh__token--keyword { font-weight: 500; }
  .ot-source-code :is(.sh__token--string, .sh__token--jsxliterals, .sh__token--comment) {
    font-family: var(--ot-expression); font-style: italic; font-stretch: 100%; letter-spacing: 0;
    font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1;
  }

  /* The bracket: a hairline joining the lines, hooked at both ends. Copying runs the accent down it. */
  .ot-source-code::before, .ot-source-code::after {
    content: ""; position: absolute; inset-block: 0.55rem; inset-inline-start: calc(var(--ot-source-gutter) - 0.9rem); width: 0.3rem;
    border: var(--ot-hairline) solid var(--ot-rule-strong); border-inline-end: 0; pointer-events: none;
  }
  .ot-source-code::after { border-color: var(--ot-accent); border-inline-start-width: var(--ot-stroke); opacity: 0; }
  .ot-source[data-copied] .ot-source-code::after { animation: ot-source-run var(--ot-adagio) var(--ot-breath) both; }
  @keyframes ot-source-run {
    0%   { opacity: 1; clip-path: inset(0 0 100% 0); }
    55%  { opacity: 1; clip-path: inset(0 0 0 0); }
    100% { opacity: 0; clip-path: inset(0 0 0 0); }
  }

  /* gloss: the glossed manuscript, and Knuth's literate programming. A line that is only a comment is
     what someone wrote about the code, so wide, it leaves the code for the outer margin and stands beside
     the line it explains (an absolute block keeps its place in the flow, so it lands level with that line)
     while the code closes up. Pointing at either inks the other. Narrow, the notes stay in the lines. */
  .ot-source-gloss { display: block; }
  .ot-source[data-variant="gloss"] .ot-source-gloss > .sh__line { color: var(--ot-graphite); transition: color var(--ot-allegro); }
  @container (min-width: 46rem) {
    .ot-source[data-variant="gloss"] .ot-source-code { padding-inline-end: 15.5rem; padding-block-end: calc(0.25rem + var(--ot-source-tail, 0px)); }
    .ot-source-gloss {
      position: absolute; inset-inline-end: 0; inline-size: 14rem; padding-block-start: 0.3rem;
      font-size: var(--ot-pp); line-height: var(--ot-pp-lh); letter-spacing: 0;
    }
    .ot-source-gloss > .sh__line { min-block-size: 0; padding-inline-start: 0; text-indent: 0; }
    .ot-source-gloss > .sh__line::before { visibility: hidden; } /* still counted, so the code keeps its true numbers */
    .ot-source-gloss .sh__token--comment { line-height: inherit; }
    .ot-source-slashes { display: none; }
    .ot-source[data-variant="gloss"] .ot-source-gloss:is(:hover, :has(+ .sh__line:hover)) > .sh__line { color: var(--ot-ink); }
    .ot-source[data-variant="gloss"] .ot-source-gloss:hover + .sh__line { --sh-identifier: var(--ot-ink); --sh-property: var(--ot-ink); --sh-sign: var(--ot-graphite); color: var(--ot-ink); }
    .ot-source[data-variant="gloss"] .ot-source-gloss:hover + .sh__line::before { opacity: 1; color: var(--ot-ink); }
  }

  /* passage: the reader's pencil line down the margin beside the lines that matter. The bracket that
     joined the whole system gathers to the passage and inks; every other line recedes to pencil.
     Copying runs the accent down the passage, line by line. */
  .ot-source[data-variant="passage"] .ot-source-code::before, .ot-source[data-variant="passage"] .ot-source-code::after { content: none; }
  .ot-source[data-variant="passage"] .sh__line:not([data-passage]) {
    color: var(--ot-pencil); --sh-keyword: var(--ot-pencil); --sh-entity: var(--ot-pencil); --sh-class: var(--ot-pencil);
    --sh-identifier: var(--ot-pencil); --sh-property: var(--ot-pencil); --sh-string: var(--ot-pencil); --sh-jsxliterals: var(--ot-pencil);
  }
  .ot-source[data-variant="passage"] .sh__line:not([data-passage]) .sh__token--keyword { font-weight: 400; }
  .ot-source[data-variant="passage"] .sh__line[data-passage] { color: var(--ot-ink); --sh-identifier: var(--ot-ink); --sh-property: var(--ot-ink); --sh-sign: var(--ot-graphite); }
  .ot-source[data-variant="passage"] .sh__line[data-passage]::before { opacity: 1; color: var(--ot-ink); }
  .ot-source[data-variant="passage"] .sh__line[data-passage]::after {
    content: ""; position: absolute; inset-block: 0; inset-inline-start: -0.9rem; width: 0.3rem;
    border-inline-start: var(--ot-stroke) solid var(--ot-ink); pointer-events: none;
  }
  .ot-source[data-variant="passage"] .sh__line[data-passage]:not([data-passage] + [data-passage])::after { inset-block-start: 0.3rem; border-block-start: var(--ot-hairline) solid var(--ot-ink); }
  .ot-source[data-variant="passage"] .sh__line[data-passage]:not(:has(+ [data-passage]))::after { inset-block-end: 0.3rem; border-block-end: var(--ot-hairline) solid var(--ot-ink); }
  .ot-source[data-variant="passage"][data-copied] .sh__line[data-passage]::after { animation: ot-source-pass var(--ot-andante) var(--ot-breath) calc(var(--k, 0) * var(--ot-arpeggio)) both; }
  @keyframes ot-source-pass { 0%, 40% { border-color: var(--ot-accent); } 100% { border-color: var(--ot-ink); } }

  /* Unwrapped: each line is kept whole and runs on past the frame, cropped by its end as SPECTRA's rule crops its word;
     the lines scroll sideways inside <code>. The lines stop being positioned, so the numbers (and the passage's line)
     are placed from the <pre>, outside the scroller: they keep their place, at the height the line gives them. */
  .ot-source[data-wrap="off"] .ot-source-code { white-space: pre; overflow-wrap: normal; }
  .ot-source[data-wrap="off"] .ot-source-code > code {
    overflow-x: auto; overscroll-behavior-x: contain; padding-block-end: var(--ot-space-2);
    scrollbar-width: thin; scrollbar-color: var(--ot-rule-strong) transparent;
  }
  .ot-source[data-wrap="off"] .ot-source-code > code:focus-visible { outline-offset: 6px; }
  .ot-source[data-wrap="off"] .ot-source-code .sh__line { position: static; inline-size: max-content; min-inline-size: 100%; }
  .ot-source[data-wrap="off"] .ot-source-code .sh__line::before { inset-block-start: auto; inset-inline-start: 0; margin-block-start: 0.1em; }
  .ot-source[data-wrap="off"][data-variant="passage"] .sh__line[data-passage]::after { inset-block: auto; inset-inline-start: calc(var(--ot-source-gutter) - 0.9rem); block-size: var(--ot-source-lh); margin-block-start: 0; }
  .ot-source[data-wrap="off"][data-variant="passage"] .sh__line[data-passage]:not([data-passage] + [data-passage])::after { inset-block-start: auto; margin-block-start: 0.3rem; block-size: calc(var(--ot-source-lh) - 0.3rem); }
  .ot-source[data-wrap="off"][data-variant="passage"] .sh__line[data-passage]:not(:has(+ [data-passage]))::after { inset-block-end: auto; block-size: calc(var(--ot-source-lh) - 0.3rem); }
  .ot-source[data-wrap="off"][data-variant="passage"] .sh__line[data-passage]:not([data-passage] + [data-passage]):not(:has(+ [data-passage]))::after { block-size: calc(var(--ot-source-lh) - 0.6rem); }
  @media (forced-colors: active) {
    .ot-source-code::before, .ot-source[data-variant="passage"] .sh__line[data-passage]::after { border-color: CanvasText; }
  }
}
